registerItem({
  id: 530060,
  onEquip(ctx) {
    let $g, $r;
    $g = ctx.getenchantgrade();
    $r = ctx.getrefine();
    ctx.bonus("bCritical", 5);
    ctx.bonus2("bSkillAtk", "IG_RADIANT_SPEAR", 15 + 5 * ($r / 3));
    ctx.bonus("bAtkRate", ($r / 2));
    ctx.bonus("bBaseAtk", 25 * ($r / 2));
    if ($r >= 7) {
      ctx.bonus("bCritAtkRate", 20);
      if ($r >= 9) {
        ctx.bonus("bCRate", 5);
        ctx.bonus("bCritical", 15);
        if ($r >= 11) {
          ctx.bonus2("bSkillAtk", "IG_RADIANT_SPEAR", 15);
        }
      }
    }
    if ($g >= "ENCHANTGRADE_D") {
      ctx.bonus("bPAtk", 5);
      if ($g >= "ENCHANTGRADE_C") {
        ctx.bonus2("bSkillAtk", "IG_RADIANT_SPEAR", 15);
        if ($g >= "ENCHANTGRADE_B") {
          ctx.bonus("bLongAtkRate", 10);
          if ($g >= "ENCHANTGRADE_A") {
            ctx.bonus("bPAtk", 3 * ($r / 2));
          }
        }
      }
    }

  },
});

